sect2.example:
    Criando uma instância usando uma expressão arbitrária


     O exemplo mostra várias expressões arbitrárias válidas que produzem um nome de classe:
     uma chamada de função, uma concatenação de strings e a constante ::class.



<?php

class ClasseA extends \stdClass {}
class ClasseB extends \stdClass {}
class ClasseC extends ClasseB {}
class ClasseD extends ClasseA {}

function obterAlgumaClasse(): string
{
    return 'ClasseA';
}

var_dump(new (obterAlgumaClasse()));
var_dump(new ('Classe' . 'B'));
var_dump(new ('Classe' . 'C'));
var_dump(new (ClasseD::class));
?>


    &example.outputs.8;


object(ClasseA)#1 (0) {
}
object(ClasseB)#1 (0) {
}
object(ClasseC)#1 (0) {
}
object(ClasseD)#1 (0) {
}

    Atribuição de Objetos


<?php
class SimpleClass {
    public string $var;
}

$instance = new SimpleClass();

$assigned   =  $instance;
$reference  =& $instance;

$instance->var = '$assigned terá esse valor';

$instance = null; // $instance e $reference tornam-se nulos

var_dump($instance);
var_dump($reference);
var_dump($assigned);
?>


    &example.outputs;


NULL
NULL
object(SimpleClass)#1 (1) {
  ["var"]=>
  string(25) "$assigned terá esse valor"
}

    Criando novos objetos


<?php

class Test
{
    public static function getNew()
    {
        return new static();
    }
}

class Child extends Test {}

$obj1 = new Test();  // Usando o nome da classe
$obj2 = new $obj1(); // Usando a variável que contém o objeto
var_dump($obj1 !== $obj2);

$obj3 = Test::getNew();   // Usando o método da classe
var_dump($obj3 instanceof Test);

$obj4 = Child::getNew();  // Usando o método através da classe filha
var_dump($obj4 instanceof Child);

?>


    &example.outputs;


bool(true)
bool(true)
bool(true)

    Acessando um membro de um objeto recém-criado


<?php
echo (new DateTime())->format('Y'), PHP_EOL;

// Os parênteses ao redor do objeto são opcionais a partir do PHP 8.4.0
echo new DateTime()->format('Y'), PHP_EOL;
?>


    &example.outputs.similar;


2025
2025

    Acesso a propriedade vs. chamada de método


<?php
class Foo
{
    public $bar = 'propriedade';

    public function bar() {
        return 'método';
    }
}

$obj = new Foo();
echo $obj->bar, PHP_EOL, $obj->bar(), PHP_EOL;


    &example.outputs;


propriedade
método

    Chamando uma função anônima armazenada em uma propriedade


<?php
class Foo
{
    public $bar;

    public function __construct() {
        $this->bar = function() {
            return 42;
        };
    }
}

$obj = new Foo();

echo ($obj->bar)(), PHP_EOL;


    &example.outputs;


42

    Herança simples de classe


<?php
class SimpleClass
{
    function displayVar()
    {
        echo "Classe pai\n";
    }
}

class ExtendClass extends SimpleClass
{
    // Redefine o método pai
    function displayVar()
    {
        echo "Classe Herdeira\n";
        parent::displayVar();
    }
}

$extended = new ExtendClass();
$extended->displayVar();
?>


    &example.outputs;


Classe Herdeira
Classe Pai

sect3.example:
     Métodos compatíveis em classes filhas


<?php

class Base
{
    public function foo(int $a) {
        echo "Valid\n";
    }
}

class Extend1 extends Base
{
    function foo(int $a = 5)
    {
        parent::foo($a);
    }
}

class Extend2 extends Base
{
    function foo(int $a, $b = 5)
    {
        parent::foo($a);
    }
}

$extended1 = new Extend1();
$extended1->foo();
$extended2 = new Extend2();
$extended2->foo(1);


     &example.outputs;


Valid
Valid

     Erro fatal quando um método de classe filha remove um parâmetro


<?php

class Base
{
    public function foo(int $a = 5) {
        echo "Válido\n";
    }
}

class Extend extends Base
{
    function foo()
    {
        parent::foo(1);
    }
}


     &example.outputs.8.similar;


Fatal error: Declaration of Extend::foo() must be compatible with Base::foo(int $a = 5) in /in/evtlq on line 13

     Erro fatal quando um método de classe filha torna obrigatório um parâmetro opcional


<?php

class Base
{
    public function foo(int $a = 5) {
        echo "Válido\n";
    }
}

class Extend extends Base
{
    function foo(int $a)
    {
        parent::foo($a);
    }
}


